catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    supported_vendors = ['Microsoft PC', 'Tomcat', 'LinuxServer', 'Azure', 'Apache', 'IIS', 'F5'];
    var endpoint = g_form.getValue('endpoint');
    var send_certificate_to_end_user = g_form.getValue('send_certificate_to_end_user');
    var passwordProtectedFormats = ['PFX', 'P12', 'JKS'];
    if (endpoint === 'true') {
        g_form.setDisplay("vendor_csr", true);
        g_form.setMandatory("vendor_csr", true);
        g_form.clearOptions("vendor_csr");
        g_form.addOption("vendor_csr", "", "Select");
        for (var itr = 0; itr < supported_vendors.length; itr++) {
            g_form.addOption("vendor_csr", supported_vendors[itr], supported_vendors[itr]);
        }
        if (send_certificate_to_end_user == "1") {
			// alert(JSON.stringify(fieldOptions));
            for (var i = 0; i < passwordProtectedFormats.length; i++) {
                g_form.removeOption('certificate_issuance_format', passwordProtectedFormats[i]);
            }
        }


    } else {
        g_form.setMandatory("vendor_csr", false);
        g_form.setDisplay("vendor_csr", false);
        g_form.clearOptions('vendor_csr');
        g_form.clearValue("vendor_csr");
        g_form.clearOptions('device_name_csr');
        g_form.clearValue('device_name_csr');
        g_form.setMandatory('device_name_csr', false);
        g_form.setDisplay('device_name_csr', false);
        g_form.clearValue('key_vault_name');
        g_form.clearOptions('key_vault_name');
        g_form.setMandatory('key_vault_name', false);
        g_form.setDisplay('key_vault_name', false);
        g_form.clearValue('csr_location');
        g_form.setMandatory('csr_location', false);
        g_form.setDisplay('csr_location', false);

    }

}
